def getSmallestEvenElementIndex (startFromIdx,lstToSearch):
    """Return index of minimum element among those starting from idx and up to final element"""
    minIndex=-1;

    try :
        currentMinVal=float("inf");
        for i in range (startFromIdx,len(lstToSearch)):
            valAtCurrentIdx = float(lstToSearch[i])
            if valAtCurrentIdx <=currentMinVal:
                currentMinVal=valAtCurrentIdx ;
                minIndex=i;

    except ValueError :
        print ("getSmallestEvenElementIndex() could not convert string to floating point")

    finally :
        pass

    return minIndex

