def encode_vigenere(s: str, k: str):
    """
    takes as input string and key. Returns encoded string.
    """
    return "".join([chr(((ord(ch) + ord(k[i % len(k)])) % 26) + ord("a")) for i, ch in enumerate(s)])


def decode_vigenere(s: str, k: str):
    """
    takes as input string and key. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - ord(k[i % len(k)]) + 26) % 26) + ord("a")) for i, ch in enumerate(s)])


print(decode_vigenere(encode_vigenere("abcdefgh", "abc"), "abc"))


def encode_rot13(s: str):
    """
    returns encoded string by rotating characters by 13 in the alphabet.
    """
    return "".join([chr(((ord(ch) - 13 + 26) % 26) + ord("a")) for ch in s])


def decode_rot13(s: str):
    """
    takes as input string encoded with encode_rot13 function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) + 13 - 26) % 26) + ord("a")) for ch in s])


print(decode_rot13(encode_rot13("abcdefgh")))


def encode_caesar(s: str, k: int):
    """
    takes as input string and key. Returns encoded string.
    """
    return "".join([chr(((ord(ch) + k - ord("a")) % 26) + ord("a")) for ch in s])


def decode_caesar(s: str, k: int):
    """
    takes as input string and key. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - k - ord("a")) % 26) + ord("a")) for ch in s])


