    """
    takes as input string. Returns encoded string in binary format.
    """
    return " ".join([format(ord(ch), 'b') for ch in s])


def decode_binary(s: str):
    """
    takes as input string. Returns decoded string in binary format.
    """
    return "".join([chr(int(ch, 2)) for ch in s.split(" ")])


