def qsort_max(_list, left=None, right=None, topN=10):
    _length = len(_list)
    i, j = (left or 0)+1, (right or _length)-1
    pivot = random.choice((i+j))
    while True:
        while i < j and _list[i] >= _list[pivot]: i += 1;
        while i < j and _list[j] <= _list[pivot]: j -= 1;

        if i == j: break

        swap(_list, i , j); i+=1; j-=1

    swap(_list, i, pivot)
    if i > (topN + left or 0): qsort_max(_list, left=left, right=i-1, topN=topN)
    elif i < ((topN + left or 0) - (_length - right)): qsort_max(_list, left=i+1, right=right, topN=topN)

